select *
  from kardex_g
 where cod_alm = '06'
   and tp_transac = '29'
   and serie = 2
   and numero in (
                  221309, 221307, 221304
   );

-- 663.69
select *
  from kardex_d
 where cod_alm = 'D2'
   and tp_transac = '29'
   and serie = 1
   and numero in (1978498);


